'use strict';
function setLayout(mode){listView=mode==='list';if(listView)zoom=1;state.settings.layout=listView?'list':'canvas';save();renderBoard();toast(listView?'List view · browse your notes in order.':'Canvas view · move your notes freely.');}
function snapCanvas(){const arranged=NotaCanvas.alignLeft(state.items,{workspace:state.active,ids:visibleItems().map(n=>n.id)});if(!arranged.length){toast('Open a note on this workspace to align it.');return;}listView=false;zoom=1;state.settings.layout='canvas';for(const n of arranged)touch(n);renderBoard();$('#board-scroll').scrollTo({left:0,top:0,behavior:'instant'});toast('Notes aligned left on the canvas. Drag a title bar to rearrange.');}
function editAudio(n){
 const credit=n.sampleId==='project-audio'?`<p class="hint audio-credit">30-second music preview by Nastelbom via <a href="https://pixabay.com/music/corporate-no-copyright-music-617081/" target="_blank" rel="noopener">Pixabay</a>. This sample demonstrates playback. Convert spoken recordings to capture their words.</p>`:'';
 modal('Audio note',`<h3 class="audio-note-title">${esc(n.title)}</h3><audio id="audio-player" controls preload="metadata" src="${esc(n.data||'')}" style="width:100%"></audio>${n.caption?`<p>${esc(n.caption)}</p>`:''}${credit}<section class="audio-transcript-section"><div class="field"><label for="audio-transcript">Transcript</label><textarea id="audio-transcript" rows="7" maxlength="100000" placeholder="Convert this recording to keep its words here.">${esc(n.transcript||'')}</textarea></div><p class="hint">Your transcript saves inside this audio note. The original recording stays unchanged.</p></section>`,`<button class="danger" id="delete-item">Delete recording</button><button class="secondary" id="download-audio">Export audio</button><button class="secondary" id="audio-transcribe">${n.transcript?'Convert again':'Convert to text'}</button><button class="primary" id="audio-done">Save to workspace</button>`,false,n);
 $('#audio-transcript').oninput=e=>{n.transcript=e.target.value;touch(n);};$('#delete-item').onclick=()=>deleteItem(n);$('#download-audio').onclick=()=>download(n.data,n.title+'.'+NotaAudio.extension(n.data));$('#audio-transcribe').disabled=!n.data;$('#download-audio').disabled=!n.data;$('#audio-transcribe').onclick=()=>transcriptionModal(n);$('#audio-done').onclick=()=>finishWindow(n,'open');
}
function editorTool(item){if(item.type==='note')return item.inputMode==='handwriting'?'handwrite':item.inputMode?null:'note';if(item.type==='sketch')return ['handwriting','ink'].includes(item.drawing?.mode)?'ink':'sketch';return item.type==='audio'?'voice':item.type==='task'?'task':null;}
function updateEditorRibbon(item){const selected=editorTool(item);$$('.editor-ribbon [data-action]').forEach(button=>{if(button.dataset.action===selected)button.setAttribute('aria-current','true');else button.removeAttribute('aria-current');});}
function editorRibbon(item){const selected=editorTool(item);return `<nav class="editor-ribbon tools" aria-label="Create on this workspace">${[['menu','layout-grid','Desk'],['sketch','pencil','Sketch'],['ink','pen-tool','Ink'],['handwrite','pen-line','Handwrite'],['task','list-todo','Task'],['import','paperclip','Import'],['voice','mic','Voice']].map(([a,i,t])=>`<button data-action="${a}" aria-label="${a==='menu'?'Open Desk menu':a==='import'?'Import a file':'Create '+t.toLowerCase()}" ${selected===a?'aria-current="true"':''}><i data-lucide="${i}"></i><span>${t}</span></button>`).join('')}</nav>`;}
function workspaceViewModal(){modal('Workspace view',`<p>Arrange notes freely on the canvas, or browse them as a list.</p><div class="view-options"><button data-action="layout" data-layout-toggle aria-label="Switch workspace layout">Canvas / list</button><button data-action="zoom-out" aria-label="Zoom out">−</button><button data-action="zoom-reset" data-zoom-value>100%</button><button data-action="zoom-in" aria-label="Zoom in">+</button><button data-action="compare">Compare notes</button></div><p class="hint">You can move notes by their title bars. Use Focus view for more space.</p>`);renderBoard();}
function cloudConsent(signal){
 if(NotaPlatform.cloudState().allowed)return Promise.resolve(true);
 if(signal?.aborted)return Promise.reject(new DOMException('Cancelled','AbortError'));
 return new Promise((resolve,reject)=>{
  const layer=document.createElement('div');layer.className='choice-overlay';layer.innerHTML=`<section class="choice-box" role="dialog" aria-modal="true" aria-labelledby="cloud-choice-title"><h2 id="cloud-choice-title">Allow cloud AI?</h2><p>When local AI cannot reply, Nth Nota sends your request, selected text or current note context, and recent chat to Cloudflare and, when configured, Groq to generate a reply.</p><p>Providers process this text under their data policies. Daily limits apply. Your other notes and original audio files are not sent by this feature.</p><p>Local AI and your notes remain available without cloud consent. You can change this choice in Settings.</p><p><a href="https://developers.cloudflare.com/workers-ai/platform/data-usage/" target="_blank" rel="noopener">Cloudflare data policy</a> · <a href="https://console.groq.com/docs/your-data" target="_blank" rel="noopener">Groq data policy</a></p><div class="choice-buttons"><button class="secondary" data-choice-cancel>Keep AI on device</button><button class="primary" id="cloud-choice-allow">Allow cloud AI</button></div></section>`;
  const previous=document.activeElement,under=$('.modal'),wasInert=under?.inert;if(under)under.inert=true;document.body.append(layer);
  const finish=(accepted,cancelled=false)=>{signal?.removeEventListener('abort',abort);layer.remove();if(under?.isConnected)under.inert=wasInert;if(!cancelled){NotaPlatform.allowCloud(accepted);const status=$('#ai-cloud-status');if(status)status.textContent=accepted?'Cloud backup is on. Your request, selected text or current note, and recent chat may go to Cloudflare or Groq. Free daily limits apply. Change this in Settings.':'Free cloud is off. Text stays on this phone. Change this in Settings.';}if(previous?.isConnected)previous.focus({preventScroll:true});cancelled?reject(new DOMException('Cancelled','AbortError')):resolve(accepted);};
  const abort=()=>finish(false,true);signal?.addEventListener('abort',abort,{once:true});layer.querySelector('[data-choice-cancel]').onclick=()=>finish(false);layer.querySelector('#cloud-choice-allow').onclick=()=>finish(true);layer.querySelector('[data-choice-cancel]').focus();
 });
}
function tutorialModal(replay=false){
 if(!NotaTour.fullToursEnabled)return false;
 NotaTour.dismiss();
 if(NotaTourDemo.active)NotaTourDemo.stop({notify:false});
 modal('Find your way around',`<p>Choose how you would like to explore Nth Nota. Move either guide by its three-line handle, and continue at your own pace.</p><div class="tutorial-choices"><div><button id="tutorial-live" class="primary">Start a live tour</button><p class="hint">Tips on your own desk. Your changes save as usual.</p></div><span class="tutorial-or" aria-label="or"><i></i><em>OR</em><i></i></span><div><button id="tutorial-practice" class="primary">Start tutorial</button><p class="hint">Try the tools on a practice desk. Practice does not save.</p></div></div>`);
 $('#tutorial-live').onclick=()=>NotaTour.start(replay);
 $('#tutorial-practice').onclick=()=>{closeModal();NotaTourDemo.start({onFinish:()=>{if(localStorage.getItem('nota-tour-version')!=='2')permissionsModal(true);}});};
}
function permissionsModal(fromTour=false){
 const native=NotaPlatform.isAndroid;modal('Your permission choices',`<p>Choose the features you want. Every choice is optional; your notes work without these permissions.</p><section class="permission-card"><h3>Microphone</h3><p>Record voice notes when you press Start recording. Allowing access here does not start a recording.</p><div><button class="secondary" id="permission-mic">Allow microphone</button><span class="permission-state" id="permission-mic-state" role="status"></span></div></section><section class="permission-card"><h3>Task notifications</h3><p>Receive reminders or show an ongoing task card. You choose which tasks notify you. Android controls sound, delivery and dismissal.</p><div><button class="secondary" id="permission-notifications">Allow notifications</button><span class="permission-state" id="permission-notice-state" role="status"></span></div></section><section class="permission-card"><h3>Cloud AI</h3><p>Local AI is automatic where supported. Cloudflare or Groq can help when it is unavailable, after you allow selected text or note context and recent chat to leave this device.</p><div><button class="secondary" id="permission-cloud">Choose cloud AI</button><span class="permission-state" id="permission-cloud-state" role="status"></span></div></section><p class="hint">You can revisit these choices in Settings. Skipping or closing this screen never grants permission or cloud consent.</p><div class="privacy-tools"><button class="secondary" id="permission-system">Open Android app settings</button><button class="secondary" id="permission-privacy">Privacy & data</button></div>`,`<button class="primary" id="permissions-done">Continue to my desk</button>`);
 const refresh=()=>{if(!$('#permission-mic-state'))return;const p=NotaPlatform.permissions(),c=NotaPlatform.cloudState();$('#permission-mic-state').textContent=p.microphone?'Allowed':native?'Not allowed':'Ask when recording';$('#permission-notice-state').textContent=p.notifications?'Allowed':native?'Not allowed':'Browser support varies';$('#permission-cloud-state').textContent=!c.configured?'Unavailable in this build':c.allowed?'Allowed':c.decided?'Off':'Not chosen';};refresh();window.addEventListener('nota-permissions',refresh);mediaCleanup=()=>window.removeEventListener('nota-permissions',refresh);
 $('#permission-mic').onclick=async()=>{if(native){NotaPlatform.microphone();return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(t=>t.stop());$('#permission-mic-state').textContent='Allowed';}catch{toast('Microphone permission was not granted. You can choose it when recording.');}};
 $('#permission-notifications').onclick=async()=>{if(native)NotaPlatform.alerts();else if('Notification'in window){try{$('#permission-notice-state').textContent=await Notification.requestPermission();}catch{toast('Notifications are unavailable in this browser.');}}else toast('Notifications are unavailable in this browser.');};
 $('#permission-cloud').disabled=!NotaPlatform.cloudState().configured;$('#permission-cloud').onclick=async()=>{if(NotaPlatform.cloudState().allowed){NotaPlatform.allowCloud(false);refresh();return;}await cloudConsent();refresh();};$('#permission-system').hidden=!native;$('#permission-system').onclick=()=>NotaPlatform.permissionSettings();$('#permission-privacy').onclick=()=>privacyModal(()=>permissionsModal(fromTour));const done=()=>{localStorage.setItem('nota-tour-version','2');closeModal();};$('#permissions-done').onclick=done;$('#close-modal').onclick=done;if(fromTour)$('.backdrop').addEventListener('click',e=>{if(e.target===$('.backdrop'))done();});
}
function taskAlertModal(n,t){const r=t.notification||{};modal('Task notification',`<p><strong>${esc(t.text||'Untitled task')}</strong></p><div class="task-alert-options"><label class="task-line"><input type="checkbox" id="task-alert-timed" ${r.when?'checked':''}> Notify me at a time</label><div class="field"><label for="task-alert-date">When</label><input type="datetime-local" id="task-alert-date" value="${r.when?new Date(r.when-new Date(r.when).getTimezoneOffset()*60000).toISOString().slice(0,16):''}"></div><label class="task-line"><input type="checkbox" id="task-alert-ongoing" ${r.ongoing?'checked':''}> Keep an ongoing task notification</label></div><p class="hint">With a time, the card appears when the reminder arrives. Without a time, an ongoing card appears now. Android may allow you to dismiss it. Complete or Stop showing removes the card.</p><p id="task-alert-permission" role="status">${NotaPlatform.permissions().notifications?'Notifications are allowed.':'Allow notifications to receive this alert.'}</p>`,`<button class="secondary" id="task-alert-permission-button">Notification choices</button><button class="secondary" id="task-alert-remove">Remove alert</button><button class="primary" id="task-alert-save">Save</button>`);
 $('#task-alert-date').disabled=!r.when;$('#task-alert-timed').onchange=e=>$('#task-alert-date').disabled=!e.target.checked;$('#task-alert-permission-button').onclick=()=>{if(NotaPlatform.isAndroid)NotaPlatform.alerts();else toast('Task notifications require the Android app.');};$('#task-alert-remove').onclick=()=>{delete t.notification;touch(n);editTask(n);};$('#task-alert-save').onclick=()=>{const timed=$('#task-alert-timed').checked,ongoing=$('#task-alert-ongoing').checked,when=timed?new Date($('#task-alert-date').value).getTime():0;if(timed&&(!Number.isFinite(when)||when<=Date.now())){toast('Choose a future date and time.');return;}if(t.done&&(timed||ongoing)){toast('Uncheck the completed task before setting a notification.');return;}if(!NotaPlatform.isAndroid&&(timed||ongoing)){toast('Task notifications require the Android app. Your task is saved.');return;}if(timed||ongoing)t.notification={when,ongoing,rev:Date.now()};else delete t.notification;touch(n);editTask(n);if(!NotaPlatform.permissions().notifications&&(timed||ongoing))toast('Alert saved. Allow notifications in Settings to receive it.');};
}
async function privacyModal(back=settingsModal){if(typeof back!=='function')back=settingsModal;
 modal('Privacy & data',`<div class="privacy-tools"><button class="secondary" id="privacy-backup">Export or restore backup</button><button class="secondary" id="privacy-choices">Permissions & AI choices</button><button class="secondary" id="privacy-reports">AI reports</button><button class="danger" id="privacy-delete">Delete all local data</button></div><div id="privacy-policy" class="privacy-copy" role="document">Loading the bundled privacy policy…</div>`,`<button class="secondary" id="privacy-back">Back</button>`);$('#privacy-back').onclick=back;$('#privacy-backup').onclick=backupModal;$('#privacy-choices').onclick=permissionsModal;$('#privacy-reports').onclick=reportInbox;$('#privacy-delete').onclick=deleteLocalDataModal;
 try{const html=await(await fetch('./privacy.html')).text(),d=new DOMParser().parseFromString(html,'text/html');if($('#privacy-policy'))$('#privacy-policy').innerHTML=sanitize(d.querySelector('main')?.innerHTML||'');}catch{if($('#privacy-policy'))$('#privacy-policy').textContent='The privacy policy could not load. Contact An Nth Experience at annthexperience@gmail.com.';}
}
function deleteLocalDataModal(){modal('Delete all local data?',`<p>This removes your notes, attachments, chat history, saved reports, reminders and workspaces from this app on this device. Export a backup first if you want to keep a copy.</p><p>Copies you exported and data already processed by providers are not erased by this action.</p><div class="field"><label for="delete-local-confirm">Type DELETE to confirm</label><input id="delete-local-confirm" autocomplete="off"></div>`,`<button class="secondary" id="delete-local-cancel">Keep my data</button><button class="danger" id="delete-local-go">Delete local data</button>`);$('#delete-local-cancel').onclick=privacyModal;$('#delete-local-go').onclick=async()=>{if($('#delete-local-confirm').value!=='DELETE'){toast('Type DELETE to confirm.');return;}if(saveConflict||!db){toast('Resolve the storage problem before deleting local data. Export a backup first.');return;}closeModal();NotaPlatform.stopRead();NotaPlatform.allowCloud(false);state=seed();state.items=[];state.assistantConversations={};state.aiReports=[];selected.clear();currentView='all';$('#search').value='';render();save();await persistDesk();toast(saveConflict?'Could not delete: resolve the save conflict first.':'Local desk cleared. Existing exported backups are unchanged.');};}
function reportReply(text){modal('Report an AI reply',`<p>Report an offensive, unsafe or misleading reply to An Nth Experience. Review what you send; your original note and other chat messages are excluded.</p><div class="field"><label for="report-reason">Reason</label><select id="report-reason"><option>Unsafe or offensive</option><option>Misleading or incorrect</option><option>Outside the app’s purpose</option><option>Other</option></select></div><div class="field"><label for="report-text">Reply excerpt</label><textarea id="report-text" maxlength="8000">${esc(text.slice(0,8000))}</textarea></div><div class="field"><label for="report-details">Details (optional)</label><textarea id="report-details" maxlength="2000"></textarea></div><label class="task-line"><input type="checkbox" id="report-consent"> Send this excerpt and these details to the developer through Cloudflare for review.</label><p class="hint">Submitted reports are separate from cloud AI consent. Reports may be kept for up to 30 days. A failed submission stays on this device until you retry or delete it.</p>`,`<button class="secondary" id="report-cancel">Cancel</button><button class="primary" id="report-send">Send report</button>`);$('#report-cancel').onclick=closeModal;$('#report-send').onclick=async()=>{if(!$('#report-consent').checked){toast('Choose whether to send this report before submitting.');return;}const r={id:uid(),reason:$('#report-reason').value,text:$('#report-text').value.trim(),details:$('#report-details').value,at:Date.now(),status:'pending'};if(!r.text){toast('Include the reply excerpt you want to report.');return;}state.aiReports=state.aiReports||[];state.aiReports.push(r);state.aiReports=state.aiReports.slice(-50);save();await submitReport(r);reportInbox();};}
async function submitReport(r){try{await NotaPlatform.reportAI({id:r.id,reason:r.reason,text:r.text,details:r.details,consentAccepted:true});r.status='sent';}catch{r.status='pending';}save();await persistDesk();}
function reportInbox(){const reports=state.aiReports||[];modal('AI reports',`<p class="hint">Only reports marked Sent reached the developer. Pending reports stay on this device. They are never retried automatically.</p>${reports.map(r=>`<div class="saved-row"><span><strong>${esc(r.reason)}</strong><small>${r.status==='sent'?'Sent':'Not sent · retry needed'} · ${new Date(r.at).toLocaleDateString()}</small><small>Report ID: ${esc(r.id)}</small></span><div class="saved-actions">${r.status==='pending'?`<button class="secondary" data-report-retry="${r.id}">Retry</button>`:''}<button class="danger" data-report-delete="${r.id}" aria-label="Delete local report"><i data-lucide="trash-2"></i></button></div></div>`).join('')||'<p>No saved reports.</p>'}`);$$('[data-report-retry]').forEach(b=>b.onclick=async()=>{b.disabled=true;await submitReport(reports.find(r=>r.id===b.dataset.reportRetry));reportInbox();});$$('[data-report-delete]').forEach(b=>b.onclick=()=>{state.aiReports=reports.filter(r=>r.id!==b.dataset.reportDelete);save();reportInbox();});}

async function deviceSupportModal(){const p=NotaPlatform.permissions();modal('Device support',`<p>Notes, tasks, drawings and search work without AI. Available AI and speech features depend on this device and its installed services.</p><div class="setting-row"><span>Local writing AI</span><span id="device-ai-status" role="status">Checking…</span></div><div class="setting-row"><span>Audio transcription<small>Android 12 or newer, supported speech model and language required. Availability is checked before a transcript starts.</small></span><span>${p.androidApi&&p.androidApi<31?'Unavailable on this Android version':'Checked when transcribing'}</span></div><div class="setting-row"><span>Voice recording</span><span>${navigator.mediaDevices?.getUserMedia&&window.MediaRecorder?'Available with microphone access':'Import audio instead'}</span></div><div class="setting-row"><span>Cloud AI</span><span>${NotaPlatform.cloudState().allowed?'Allowed · daily limits apply':'Optional · consent required'}</span></div><p class="hint">Use Android’s font and display settings for larger text. Readback requires an installed offline voice. No phone brand is required for core notes.</p>`);try{const r=await NotaPlatform.localRequest('status');if($('#device-ai-status'))$('#device-ai-status').textContent=({ready:'Ready',downloadable:'Model download needed',downloading:'Downloading',busy:'Busy',unavailable:'Unavailable'})[r.status]||'Unavailable';}catch{if($('#device-ai-status'))$('#device-ai-status').textContent='Unavailable · optional cloud backup';}}

