function deleteWorkspaceModal(){
 const id=state.active,w=state.workspaces.find(w=>w.id===id);if(!w)return;
 const count=state.items.filter(n=>n.workspace===id&&!n.deletedAt).length;
 modal('Delete this workspace?',`<p>Delete <strong>${esc(w.name)}</strong>?</p><p>${count?`${count} ${count===1?'note moves':'notes move'} to Recently deleted, including saved and minimized notes. Their reminders will stop. You can restore the notes to a remaining workspace.`:'This workspace has no notes.'}</p>${state.workspaces.length===1?'<p class="hint">A new, empty Everyday workspace will take its place.</p>':''}`,`<button class="secondary" id="workspace-delete-cancel">Cancel</button><button class="danger" id="workspace-delete-confirm">Delete workspace</button>`);
 $('#workspace-delete-cancel').onclick=closeModal;$('#workspace-delete-cancel').focus();
 $('#workspace-delete-confirm').onclick=async()=>{if(saveConflict||!db){toast('Resolve the storage problem before deleting a workspace.');return;}const result=NotaCreation.removeWorkspace(state,id,{uid});selected.clear();currentView='all';$('#search').value='';closeModal();render();save();await persistDesk();toast($('#save-state').textContent.includes('Saved on device')?`${result.name} deleted.${result.count?' Notes are in Recently deleted.':''}`:'Changes could not be saved. Export a backup before leaving.');};
}
function handwritingModal(n){NotaHandwriting.open(n,{modal,esc,plain,touch,finish:()=>finishWindow(n,'open'),typing:()=>{delete n.inputMode;editItem(n);},cleanup:fn=>{mediaCleanup=fn;},flush:persistDesk,persist:fn=>{activeEditor=fn;},icons,toast});}

function openJournal(date=NotaCreative.localDate(),workspace=state.active){
 if(!NotaCreative.validDate(date)){toast('Choose a valid journal date.');return;}
 let n=state.items.find(n=>!n.deletedAt&&n.workspace===workspace&&n.inputMode==='journal'&&n.journal?.date===date);
 if(!n)n=addItem('note',{workspace,inputMode:'journal',tag:'Daily journal',title:new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}),titlePlaceholder:true,journal:NotaCreative.journal(date)});
 restoreWindow(n);creativeModal(n);
}
function createCreative(mode){if(mode==='journal'){openJournal();return;}const options={spinner:{title:'My Fidget Spinner',tag:'Fidget Spinner',spinner:NotaMisc.spinner(),h:390},dice:{title:'My Dice Tray',tag:'Dice Tray',dice:NotaMisc.dice(),h:430},scanner:{title:'A document to keep',tag:'Scanner',scanner:NotaDeskTools.scanner()},index:{title:'My custom index',tag:'Index Builder',index:NotaDeskTools.index(uid)},snippets:{title:'My Snippet Shelf',tag:'Snippet Shelf',snippets:NotaDeskTools.shelf(uid)},streak:{title:'My Streak Board',tag:'Streak Board',streak:NotaDeskTools.streak(uid)},flash:{title:'My Flash Cards',tag:'Flash Cards',flash:NotaDeskTools.flash(uid)},calculator:{title:'A little room for numbers',tag:'Calculator',calculator:NotaThinking.calculator()},choice:{title:'A choice worth thinking through',tag:'Choice Weaver',choice:NotaThinking.choice(uid)},reference:{title:'A few things worth knowing',tag:'Reference Lab',reference:NotaThinking.reference(uid)},budget:{title:'A little room in the budget',tag:'Budget planner',budget:NotaPlanning.budget(uid)},calendar:{title:'Days with a little room',tag:'Calendar',calendar:NotaPlanning.calendar()},photo:{title:'Words from a photo',tag:'Photo to text',photo:{data:'',preview:'',rotation:0,blocks:[]}},mindmap:{title:'A thought with room to grow',tag:'Mind map',mindmap:NotaCreative.newMap(uid)},math:{title:'Let the numbers tell the story',tag:'Math sheet',mathSheet:{rows:NotaCreative.mathRows(uid).map(row=>({...row,label:'',name:'',expression:'',whatIf:'',unit:''})),scenario:false}}}[mode];if(options)creativeModal(addItem('note',{inputMode:mode,...options,titlePlaceholder:true}));}
function creativeModal(n){({...NotaModeEditors,...NotaPlanningEditors,...NotaThinkingEditors,...NotaDeskEditors,...NotaScannerEditors,...NotaMiscEditors})[n.inputMode]?.(n,{modal,esc,plain,uid,titleValue:editorTitle,setTitle:setEditorTitle,calculate:NotaCore.calculate,readData,icons,toast,touch,flush:persistDesk,persist:fn=>{activeEditor=fn;},cleanup:fn=>{mediaCleanup=fn;},finish:()=>finishWindow(n,'open'),export:exportModal,assistant:n=>assistant(n),openJournal:date=>openJournal(date,n.workspace),downloadPhoto:async(data,name)=>{try{const blob=await(await fetch(data)).blob();await download(blob,(name||'Photo')+'-source.'+(blob.type==='image/png'?'png':blob.type==='image/webp'?'webp':'jpg'));}catch{toast('Could not export this photo.');}},promote:({id,title,text,task,parent,onId})=>{let child=state.items.find(n=>n.id===id&&!n.deletedAt);if(!child){child=addItem(task?'task':'note',{workspace:parent.workspace,title:title.slice(0,200),parentId:parent.id,...(task?{tasks:[{id:uid(),text,done:false}]}:{html:text.split('\n').map(p=>'<p>'+esc(p)+'</p>').join('')})});onId(child.id);touch(parent);}restoreWindow(child);editItem(child);}});}

