function bindCanvasPicker(select,onChange){select.dataset.destination=select.value;select.onchange=e=>{if(e.target.value==='__new_canvas__'){createCanvasInline(select,id=>{onChange(id);select.dataset.destination=select.value;});return;}try{onChange(select.value);select.dataset.destination=select.value;}catch(error){select.value=select.dataset.destination;toast(error.message);}};}
function calendarCard(n){const cal=n.calendar;if(cal.cardView!=='month'){const entries=[...cal.events].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<h2>${esc(n.title)}</h2><div class="creative-preview">${entries.length?entries.slice(0,3).map(e=>`<p><small>${esc(e.date)} · ${esc(e.time||'All day')}</small><br>${esc(e.title||'Untitled plan')}</p>`).join(''):'Make room for a plan, a thought, or the next step.'}</div>`;}const entries=NotaPlanning.dayEntries(cal,cal.selected);return `<div class="calendar-card-name">${esc(n.title)}</div><div class="calendar-card-head"><button data-card-action="cal-prev" aria-label="Previous calendar month"><i data-lucide="chevron-left"></i></button><strong>${new Date(cal.month+'-01T12:00:00').toLocaleDateString(undefined,{month:'long',year:'numeric'})}</strong><button data-card-action="cal-next" aria-label="Next calendar month"><i data-lucide="chevron-right"></i></button></div><div class="calendar-card-grid">${['S','M','T','W','T','F','S'].map(s=>`<small aria-hidden="true">${s}</small>`).join('')}${NotaPlanning.monthDays(cal.month).map(date=>{const count=cal.events.filter(e=>e.date===date).length;return `<button data-card-calendar-date="${date}" aria-label="${esc(new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}))}${count?' · '+count+' entries':''}" aria-pressed="${cal.selected===date}" class="${date.slice(0,7)===cal.month?'':'outside'}" ${NotaPlanning.validDate(date)?'':'disabled'}>${Number(date.slice(-2))}${count?'<span class="calendar-entry-dot" aria-hidden="true"></span>':''}</button>`;}).join('')}</div><div class="calendar-card-agenda"><strong>${esc(cal.selected)}</strong>${entries.slice(0,2).map(e=>`<button data-card-action="cal-open">${esc(e.time||'All day')} · ${esc(e.title||'Untitled plan')}</button>`).join('')||'<p class="hint">A little room in this day.</p>'}<button data-card-action="cal-open" class="calendar-card-open">Open day in planner</button></div>`;}
function draftCapsule(n){n.capsule??={sealed:false,unlockAt:0,notify:false,createdAt:Date.now()};touch(n);editItem(n);}
function capsuleMenu(){modal('Time Capsule',`<div class="assistant-intro"><h3>Notes for your future self.</h3><p>Keep a letter, a recording, or a drawing for a day ahead. Write it now, then choose when it reappears.</p></div><p class="hint">A scheduled reveal on this device. Contents remain in readable backups; this is not an encrypted privacy lock.</p><div class="capsule-create-options"><button id="capsule-letter"><i data-lucide="notebook-pen"></i> Write a letter</button><button id="capsule-voice"><i data-lucide="mic"></i> Record a message</button><button id="capsule-sketch"><i data-lucide="pencil"></i> Draw something</button></div><label class="field">Or choose something saved<select id="capsule-existing"><option value="">Choose a note, recording, or sketch…</option>${state.items.filter(n=>!n.deletedAt&&['note','audio','sketch'].includes(n.type)).map(n=>`<option value="${n.id}">${esc(n.title||'Untitled')} · ${esc(state.workspaces.find(w=>w.id===n.workspace)?.name||'Canvas')}</option>`).join('')}</select></label>`);$('#capsule-letter').onclick=()=>draftCapsule(addItem('note',{title:'For my future self',titlePlaceholder:true}));$('#capsule-sketch').onclick=()=>draftCapsule(addItem('sketch',{title:'A sketch for another day',titlePlaceholder:true}));$('#capsule-voice').onclick=()=>voiceModal(true);$('#capsule-existing').onchange=e=>{const n=state.items.find(n=>n.id===e.target.value);if(n){if(NotaThinking.capsuleClosed(n))sealedCapsule(n);else draftCapsule(n);}};}
function capsuleSettings(n){if(activeEditor){activeEditor();activeEditor=null;}const cap=n.capsule||{sealed:false,unlockAt:0,notify:false,createdAt:Date.now()},local=value=>new Date(value-new Date(value).getTimezoneOffset()*60000).toISOString().slice(0,16);modal('A day for this capsule',`<p><strong>${esc(n.title)}</strong></p><p>Choose when this ${n.type==='audio'?'message':n.type==='sketch'?'drawing':'note'} returns to you.</p><div class="planner-actions"><button data-capsule-offset="6" class="secondary">In 6 months</button><button data-capsule-offset="12" class="secondary">In a year</button></div><label class="field">Reveal date & time<input id="capsule-date" type="datetime-local" max="2199-12-31T23:59" value="${cap.unlockAt?local(cap.unlockAt):''}"></label><label class="task-line"><input id="capsule-notify" type="checkbox" ${cap.notify?'checked':''}><span>Remind me when it is ready</span></label><p class="hint">Reveals follow this device’s clock. You can choose Open early. Backups include the contents; sealing does not encrypt them. Existing note reminders are kept.</p><p id="capsule-error" role="status"></p>`,`<button id="capsule-back" class="secondary">Back</button><button id="capsule-seal" class="primary">Seal until this day</button>`);$$('[data-capsule-offset]').forEach(button=>button.onclick=()=>{$('#capsule-date').value=local(NotaThinking.capsuleOffset(Date.now(),Number(button.dataset.capsuleOffset)));});$('#capsule-back').onclick=()=>editItem(n);$('#capsule-seal').onclick=()=>{const unlockAt=new Date($('#capsule-date').value).getTime();if(!Number.isFinite(unlockAt)||unlockAt<=Date.now()||unlockAt>7258118399000||Number.isFinite(unlockAt)&&local(unlockAt)!==$('#capsule-date').value){$('#capsule-error').textContent='Choose a future date before the year 2200.';return;}n.capsule={sealed:true,unlockAt,notify:$('#capsule-notify').checked,createdAt:cap.createdAt,rev:Math.max(Date.now(),(cap.rev||0)+1)};if(n.capsule.notify&&!NotaPlatform.permissions().notifications)NotaPlatform.alerts();touch(n);finishWindow(n,'open');toast('Sealed for '+new Date(unlockAt).toLocaleDateString()+'.');};}
function sealedCapsule(n){const cap=n.capsule;modal('For another day',`<div class="sealed-capsule"><i data-lucide="hourglass"></i><h3>${esc(n.title)}</h3><p>Opens ${esc(new Date(cap.unlockAt).toLocaleString())}</p><p class="hint">Your ${n.type==='audio'?'recording':n.type==='sketch'?'drawing':'note'} is kept here until then. This is a scheduled reveal, not encrypted storage.</p></div>`,`<button class="secondary" id="capsule-change">Change reveal date</button><button class="secondary" id="capsule-early">Open early…</button>`);$('#capsule-change').onclick=()=>capsuleSettings(n);$('#capsule-early').onclick=()=>{modal('Open this capsule early?',`<p>You planned to open “${esc(n.title)}” on ${esc(new Date(cap.unlockAt).toLocaleString())}.</p><p class="hint">Type OPEN to reveal it now.</p><input id="capsule-confirm-text" aria-label="Type OPEN to reveal now" autocomplete="off">`,`<button id="capsule-keep-sealed" class="secondary">Keep sealed</button><button id="capsule-confirm-open" class="primary">Open now</button>`);$('#capsule-keep-sealed').onclick=()=>sealedCapsule(n);$('#capsule-confirm-open').onclick=()=>{if($('#capsule-confirm-text').value.trim()!=='OPEN'){$('#capsule-confirm-text').focus();return;}cap.sealed=false;cap.notify=false;touch(n);editItem(n);};};}
const capsuleReadySeen=new Set();function checkCapsuleReveals(){if(window.NotaTourDemo?.active)return;if(!state)return;let changed=false;for(const n of state.items){if(!n.deletedAt&&n.capsule?.sealed&&n.capsule.unlockAt<=Date.now()&&!capsuleReadySeen.has(n.id+':'+n.capsule.unlockAt)){capsuleReadySeen.add(n.id+':'+n.capsule.unlockAt);changed=true;if(!NotaPlatform.isAndroid&&n.capsule.notify&&!n.capsule.notifiedAt){toast('Your time capsule is ready: '+n.title);if('Notification'in window&&Notification.permission==='granted')try{new Notification('Your time capsule is ready',{body:n.title,tag:'capsule-'+n.id});}catch{}n.capsule.notifiedAt=Date.now();touch(n);}}}if(changed&&!drag)renderBoard();}
function remindersHub(){modal('Reminders',`<p class="mode-lead">A little help remembering.</p><p class="hint">Create reminders and pin canvas items to your notification panel, with or without a schedule. The labels below reflect your saved settings, not proof that a notification was delivered.</p><div class="planner-settings"><label>Canvas<select id="reminders-canvas"><option value="">All canvases</option>${state.workspaces.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select></label><label>Show<select id="reminders-kind"><option value="">Everything</option><option value="ongoing">Persistent notifications</option><option value="task">Tasks</option><option value="note">Note reminders</option><option value="capsule">Time Capsules</option></select></label></div><p id="reminders-permission" class="hint"></p><div class="planner-actions"><button id="reminders-permissions" class="secondary">Notification choices</button><button id="reminders-new" class="primary">New reminder</button><button id="reminders-add" class="secondary">Remind me about an item</button><button id="reminders-pin" class="primary">Create persistent notification</button></div><div id="reminders-list"></div>`);const refresh=()=>{const canvas=$('#reminders-canvas').value,kind=$('#reminders-kind').value,now=Date.now(),rows=NotaThinking.reminderRows(state.items).filter(r=>(!canvas||state.items.find(n=>n.id===r.item)?.workspace===canvas)&&(!kind||kind==='ongoing'?(!kind||r.ongoing):r.kind===kind));$('#reminders-permission').textContent=NotaPlatform.isAndroid?(NotaPlatform.permissions().notifications?'Notifications are allowed. Android controls delivery and dismissal.':'Notifications are off. Your reminders stay saved; enable notifications when you want alerts.'):'Browser alerts need permission and an open app. Closed-app reminders use the Android build.';$('#reminders-list').innerHTML=rows.length?rows.map((r,i)=>`<section class="reminder-hub-row"><div><strong>${esc(r.title)}</strong><p>${esc(r.body)}</p><small>${r.done?'Completed / fired':r.kind==='capsule'&&r.when<=now?'Ready to open':r.ongoing?(r.when>now?'Scheduled + persistent':'Persistent notification'):r.when<=now?'Due / past time':'Scheduled'}${r.when?' · '+esc(new Date(r.when).toLocaleString()):''}</small></div><div class="planner-actions"><button data-hub-open="${i}" class="secondary">Open</button><button data-hub-edit="${i}" class="secondary">Edit</button><button data-hub-stop="${i}" class="secondary">Stop alert</button>${r.kind==='task'&&!r.done?`<button data-hub-complete="${i}" class="secondary">Complete task</button>`:''}</div></section>`).join(''):'<p class="hint">No reminders here yet. Set one for a saved note, or use a task’s bell.</p>';const source=i=>{const row=rows[Number(i)],n=state.items.find(n=>n.id===row.item);return {row,n,t:n?.tasks?.find(t=>t.id===row.task)};};$$('[data-hub-open]').forEach(b=>b.onclick=()=>{const {n}=source(b.dataset.hubOpen);restoreWindow(n);editItem(n);});$$('[data-hub-edit]').forEach(b=>b.onclick=()=>{const {row,n,t}=source(b.dataset.hubEdit);if(row.kind==='pinned')persistentNotificationModal(n);else if(row.kind==='task')taskAlertModal(n,t);else if(row.kind==='capsule')capsuleSettings(n);else reminderModal(n);});$$('[data-hub-stop]').forEach(b=>b.onclick=()=>{const {row,n,t}=source(b.dataset.hubStop);if(row.kind==='pinned')delete n.persistentNotice;else if(row.kind==='task')delete t.notification;else if(row.kind==='capsule')n.capsule.notify=false;else delete n.reminder;touch(n);persistDesk();refresh();});$$('[data-hub-complete]').forEach(b=>b.onclick=()=>{const {n,t}=source(b.dataset.hubComplete);t.done=true;delete t.notification;touch(n);persistDesk();refresh();});};$('#reminders-canvas').onchange=$('#reminders-kind').onchange=refresh;$('#reminders-permissions').onclick=()=>permissionsModal();$('#reminders-new').onclick=()=>reminderModal();$('#reminders-pin').onclick=()=>persistentNotificationModal();$('#reminders-add').onclick=()=>{modal('Choose what to remember',`<label class="field">Saved note or task list<select id="hub-reminder-source"><option value="">Choose an item…</option>${state.items.filter(n=>!n.deletedAt&&!NotaThinking.capsuleClosed(n)).map(n=>`<option value="${n.id}">${esc(n.title)}</option>`).join('')}</select></label><p class="hint">For a task list, use the bell beside the task that should notify you.</p>`,`<button id="hub-reminder-back" class="secondary">Back to Reminders</button>`);$('#hub-reminder-back').onclick=remindersHub;$('#hub-reminder-source').onchange=e=>{const n=state.items.find(n=>n.id===e.target.value);if(n){if(n.type==='task')editItem(n);else reminderModal(n);}};};refresh();}

function installEditorCompanion(item,{dates=true}={}){
 const body=$('.modal-body');
 if(['sketch','image','pdf'].includes(item.type)){body.insertAdjacentHTML('beforeend',`<label class="field">Notes about this ${item.type==='pdf'?'document':item.type==='image'?'image':'drawing'}<textarea id="editor-caption" rows="3" maxlength="100000">${esc(item.caption||'')}</textarea></label>`);$('#editor-caption').oninput=e=>{item.caption=e.target.value;touch(item);};}
 if(!$('#note-ai')&&!$('#mode-ai')){body.insertAdjacentHTML('beforeend','<button id="editor-companion" class="secondary mode-assist"><i data-lucide="sparkles"></i> '+(item.inputMode==='handwriting'?'Proofread with Writing Companion':'Writing companion')+'</button>');$('#editor-companion').onclick=()=>assistant(item);}
 installSnippetButton(item,body);NotaPolish.install(item,body);if(dates)installDateMemory(item,body);body.addEventListener('input',e=>{if(isWritingField(e.target))editorField=e.target;});body.addEventListener('focusin',e=>{if(isWritingField(e.target)&&!e.target.classList.contains('editor-title'))editorField=e.target;});
}
function isWritingField(el){return el?.matches('textarea:not(:disabled):not([readonly]),input:not(:disabled):not([readonly]):is([type=text],:not([type])),[contenteditable=true]');}
function suspendWritingEditor(item,excerpt){
 activeEditor?.();
 const fields=$$('.modal-body textarea,.modal-body input,.modal-body [contenteditable=true]').filter(el=>isWritingField(el)&&el.getClientRects().length),targets=fields.map((element,index)=>({element,label:element.labels?.[0]?.textContent?.trim()||element.getAttribute('aria-label')||element.placeholder||(element.isContentEditable?'Note text':element.classList.contains('editor-title')?'Title':'Writing '+(index+1))}));
 let index=fields.indexOf(editorField);if(index<0)index=fields.findIndex(el=>el.isContentEditable||el.tagName==='TEXTAREA');if(index<0)index=fields.findIndex(el=>!el.classList.contains('editor-title'));if(index<0)index=0;
 if(!targets.length)return null;
 const element=targets[index].element,selection=window.getSelection(),range=element.isContentEditable&&selection?.rangeCount&&element.contains(selection.anchorNode)&&element.contains(selection.focusNode)?selection.getRangeAt(0).cloneRange():null;
 let contentSelection=null;if(range&&!range.collapsed){const prefix=range.cloneRange();prefix.selectNodeContents(element);prefix.setEnd(range.startContainer,range.startOffset);const begin=prefix.toString().length;contentSelection={start:begin,end:begin+range.toString().length};}const start=element.selectionStart,end=element.selectionEnd,text=element.isContentEditable?plain(element.innerHTML):element.value,context=excerpt.trim()||(start!==end&&start!==null?text.slice(start,end):text);
 const focus=document.activeElement,fragment=document.createElement('div');fragment.hidden=true;fragment.inert=true;const aliases=[...document.querySelectorAll('#modal-root #close-modal,#modal-root #minimize-modal,#modal-root #maximize-modal')].map(el=>[el,el.id]);const classes=[...document.querySelectorAll('#modal-root .modal,#modal-root .backdrop')].map(el=>[el,el.className]);aliases.forEach(([el,id])=>el.id='suspended-'+id);classes.forEach(([el])=>{el.classList.remove('modal','backdrop');});fragment.append(...$('#modal-root').childNodes);document.body.append(fragment);const saved={item,targets,index,element,contentSelection,start,end,context,original:text,fragment,aliases,classes,persist:activeEditor,cleanup:mediaCleanup,focus};activeEditor=null;mediaCleanup=null;editorItem=null;editorField=null;return saved;
}
function resumeWritingEditor(){const saved=suspendedEditor;if(!saved)return; suspendedEditor=null;closeModal();saved.aliases.forEach(([el,id])=>el.id=id);saved.classes.forEach(([el,name])=>el.className=name);$('#modal-root').append(...saved.fragment.childNodes);saved.fragment.remove();editorItem=saved.item;editorField=saved.element;activeEditor=saved.persist;mediaCleanup=saved.cleanup;saved.focus?.focus({preventScroll:true});icons();return saved;}
function applyCompanionReply(saved,reply,append){
 if(!reply.trim())return;const el=saved.element,old=el.isContentEditable?plain(el.innerHTML):el.value,limit=el.maxLength>0?el.maxLength:100000;
 if(old!==saved.original){toast('This writing changed while the companion was open. Choose its writing field again to refresh the context.');return;}const replacingSelection=!append&&(saved.contentSelection||Number.isInteger(saved.start)&&saved.start!==saved.end),removed=saved.contentSelection?saved.contentSelection.end-saved.contentSelection.start:saved.end-saved.start,estimate=append?old.length+reply.length+2:replacingSelection?old.length-removed+reply.length:reply.length;
 if(estimate>limit){toast('This reply is too long for the selected writing. Copy a shorter passage instead.');return;}
 resumeWritingEditor();
 if(el.isContentEditable){if(!append&&saved.contentSelection){const locate=offset=>{const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(offset<=node.length)return [node,offset];offset-=node.length;}return [el,el.childNodes.length];},range=document.createRange();range.setStart(...locate(saved.contentSelection.start));range.setEnd(...locate(saved.contentSelection.end));range.deleteContents();range.insertNode(document.createTextNode(reply));}else if(append){el.insertAdjacentHTML('beforeend',reply.split('\n').map(line=>'<p>'+esc(line)+'</p>').join(''));}else el.innerHTML=reply.split('\n').map(line=>'<p>'+esc(line)+'</p>').join('');}
 else if(replacingSelection)el.setRangeText(reply,saved.start,saved.end,'end');else el.value=append?old+(old?(el.tagName==='TEXTAREA'?'\n':' '):'')+reply:reply;
 el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));activeEditor?.();touch(saved.item);el.focus({preventScroll:true});toast('Writing updated in this item.');
}

function persistentNotificationModal(item=null){
 modal('Persistent notification',`<p>Keep a canvas item within reach in your notification panel.</p><label class="field">Canvas item<select id="pin-source"><option value="">Choose an item…</option>${state.items.filter(n=>!n.deletedAt&&!NotaThinking.capsuleClosed(n)).map(n=>`<option value="${n.id}" ${n===item?'selected':''}>${esc(n.title)} · ${esc(state.workspaces.find(w=>w.id===n.workspace)?.name||'Canvas')}</option>`).join('')}</select></label><p id="pin-preview" class="hint"></p><p class="hint">No date or scheduled reminder is needed. Tapping the notification opens this item. Android controls notification delivery and dismissal.</p>`,`<button id="pin-back" class="secondary">Back to Reminders</button><button id="pin-permission" class="secondary">Enable notifications</button><button id="pin-save" class="primary">Pin to notifications</button>`);
 const preview=()=>{const n=state.items.find(n=>n.id===$('#pin-source').value);$('#pin-preview').textContent=n?noteSearchText(n).slice(0,500):'Choose the item you want to keep close.';$('#pin-save').disabled=!n;};$('#pin-source').onchange=preview;$('#pin-back').onclick=remindersHub;$('#pin-permission').onclick=()=>NotaPlatform.alerts();$('#pin-save').onclick=async()=>{const n=state.items.find(n=>n.id===$('#pin-source').value&&!n.deletedAt);if(!n)return;n.persistentNotice={rev:Math.max(Date.now(),(n.persistentNotice?.rev||0)+1)};touch(n);closeModal();restoreWindow(n);await persistDesk();toast(NotaPlatform.isAndroid?'Pinned item saved. Notifications must be enabled.':'Pinned item saved. Notification panel cards use the Android app.');};preview();
}
